<div class="feature-card mb-4 monitor-filters">
<form method="get" action="<?php echo site_url($base); ?>" class="row g-3">
	<?php if ( ! empty($tab)): ?><input type="hidden" name="tab" value="<?php echo html_escape($tab); ?>"><?php endif; ?>
	<?php if ($filters['pencarian'] !== ''): ?><input type="hidden" name="pencarian" value="<?php echo html_escape($filters['pencarian']); ?>"><?php endif; ?>
	<?php if ($filters['konten'] !== ''): ?><input type="hidden" name="konten" value="<?php echo html_escape($filters['konten']); ?>"><?php endif; ?>
	<div class="col-6 col-lg-3"><label for="monitor-start" class="form-label">Mulai (WIB)</label><input id="monitor-start" type="date" class="form-control" name="mulai" value="<?php echo html_escape($filters['mulai']); ?>" required></div>
	<div class="col-6 col-lg-3"><label for="monitor-end" class="form-label">Sampai (WIB)</label><input id="monitor-end" type="date" class="form-control" name="sampai" value="<?php echo html_escape($filters['sampai']); ?>" required></div>
	<div class="col-12 col-lg-6 d-flex align-items-end gap-2"><button class="btn btn-primary" type="submit">Terapkan filter</button><a class="btn btn-outline-secondary" href="<?php echo site_url($base); ?>">Reset</a></div>
	<details class="col-12"><summary class="fw-semibold">Modul, kursus, dan filter lainnya</summary><div class="row g-3 mt-1">
	<?php $filter_options = array('modul' => array('Modul', study_monitor_modules()), 'status' => array('Status aktivitas', array('running' => 'Sedang belajar', 'completed' => 'Selesai / dikenal', 'abandoned' => 'Dihentikan'))); ?>
	<?php if ($filters['konten'] !== '' || strpos($base, 'kelola/pembelajaran/modul/') === 0 || isset(study_monitor_modules()[$tab ?? ''])): unset($filter_options['modul']); ?><input type="hidden" name="modul" value="<?php echo html_escape($filters['modul']); ?>"><?php endif; ?>
	<?php if (empty($family)): $filter_options += array('jenjang' => array('Jenjang pengguna', array('early_childhood' => 'TK', 'primary' => 'SD', 'secondary' => 'SMP', 'adult' => 'Dewasa', 'unset' => 'Belum diatur')), 'aktivitas' => array('Aktivitas pada periode', array('ada' => 'Ada aktivitas', 'belum' => 'Belum ada aktivitas')), 'urutan' => array('Urutan pengguna', array('terbaru' => 'Aktivitas terbaru', 'nama' => 'Nama A–Z')), 'kursus' => array('Kursus', array_column($courses, 'title', 'id')), 'paket' => array('Kursus dalam paket', array_column($packages, 'title', 'id'))); endif; ?>
	<?php foreach ($filter_options as $key => $option): ?><div class="col-sm-6 col-xl-4"><label for="monitor-<?php echo $key; ?>" class="form-label"><?php echo html_escape($option[0]); ?></label><select id="monitor-<?php echo $key; ?>" name="<?php echo $key; ?>" class="form-select"><option value="">Semua</option><?php foreach ($option[1] as $value => $label): ?><option value="<?php echo html_escape((string) $value); ?>"<?php echo (string) $filters[$key] === (string) $value ? ' selected' : ''; ?>><?php echo html_escape($label); ?></option><?php endforeach; ?></select></div><?php endforeach; ?>
	</div></details>
</form>
<?php if ($filters['konten'] !== ''): ?><p class="small mt-3 mb-0">Dibatasi ke konten / sesi #<?php echo html_escape($filters['konten']); ?> pada modul <?php echo html_escape(study_monitor_modules()[$filters['modul']]); ?>.</p><?php endif; ?>
<p class="monitor-note mt-3 mb-0">Periode aktif: <?php echo html_escape($filters['mulai'].' s.d. '.$filters['sampai']); ?> WIB · <?php echo html_escape(study_monitor_modules()[$filters['modul']] ?? 'Semua modul'); ?> · <?php echo $filters['status'] !== '' ? html_escape(study_monitor_state($filters['status'])) : 'Semua status'; ?><?php if ($filters['kursus'] !== ''): ?> · Kursus #<?php echo html_escape($filters['kursus']); ?><?php endif; ?><?php if ($filters['paket'] !== ''): ?> · Paket #<?php echo html_escape($filters['paket']); ?><?php endif; ?></p>
</div>
